public class Setup {
 public const string ProductId="XiaZheTeng.TVStudio";public const string StateName="xzt-install.json";public const string RegistryPath=@"Software\Microsoft\Windows\CurrentVersion\Uninstall\XiaZheTengTVStudio";
 public static string Version{get{return Assembly.GetExecutingAssembly().GetName().Version.ToString(3);}}
 static void MoveInstallDirectory(string source,string destination){source=Path.GetFullPath(source);destination=Path.GetFullPath(destination);if(!Same(Path.GetDirectoryName(source),Path.GetDirectoryName(destination)))throw new Exception("安装提交只能在同一目标目录内重命名");for(int i=0;;i++){try{Directory.Move(source,destination);return;}catch(IOException){if(i>=7)throw;Thread.Sleep(250);}catch(UnauthorizedAccessException){if(i>=7)throw;Thread.Sleep(250);}}}
 public static string DataPath{get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"XiaZheTengTV","Data");}}
 public static string DefaultPath{get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"XiaZheTengTV","App");}}
 public static string RegisteredPath(){try{using(var key=Registry.CurrentUser.OpenSubKey(RegistryPath)){return key==null?"":(key.GetValue("InstallLocation") as string??"");}}catch{return "";}}
 static string Q(string value){if(value.Contains("\"")||value.Contains("\r")||value.Contains("\n"))throw new Exception("路径包含无效字符");return "\""+value+"\"";}
 public static bool Same(string a,string b){try{return string.Equals(Path.GetFullPath(a).TrimEnd('\\','/'),Path.GetFullPath(b).TrimEnd('\\','/'),StringComparison.OrdinalIgnoreCase);}catch{return false;}}
 static bool Within(string path,string folder){return Path.GetFullPath(path).StartsWith(Path.GetFullPath(folder).TrimEnd('\\','/')+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase);}
 static string Inside(string folder,string relative){if(Path.IsPathRooted(relative))throw new Exception("安装包含有绝对路径");string path=Path.GetFullPath(Path.Combine(folder,relative));if(!Within(path,folder))throw new Exception("安装包路径越界");return path;}
 public static bool IsInstalled(string target){try{string state=Path.Combine(target,StateName);if(File.Exists(state)){var data=new JavaScriptSerializer().Deserialize<InstallState>(File.ReadAllText(state));return data!=null&&data.Product==ProductId&&Same(data.Target,target);}string exe=Path.Combine(target,"TVStudio.exe");if(!File.Exists(exe)||!File.Exists(Path.Combine(target,"adb.exe"))||!File.Exists(Path.Combine(target,"logo.ico")))return false;var version=FileVersionInfo.GetVersionInfo(exe);return version.ProductName=="SmartTV Toolkit GUI"||Same(target,RegisteredPath())&&AssemblyName.GetAssemblyName(exe).Name=="TVStudio";}catch{return false;}}
 public static string ValidateTarget(string value,string previous=""){if(string.IsNullOrWhiteSpace(value)||!Path.IsPathRooted(value))throw new Exception("请输入完整的安装路径，例如 D:\\Apps\\TVStudio");string target=Path.GetFullPath(value.Trim()).TrimEnd('\\','/');if(target.Length>180)throw new Exception("安装路径过长，请选择 180 个字符以内的目录，以兼容附带的 Windows 工具");if(Same(target,Path.GetPathRoot(target)))throw new Exception("不能直接安装到磁盘或共享根目录，请选择独立的软件文件夹");var reserved=new[]{Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData),Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86)};if(reserved.Where(x=>!string.IsNullOrEmpty(x)).Any(x=>Same(target,x)))throw new Exception("请选择独立的软件子文件夹，不要直接使用系统目录或个人文件夹");string windows=Environment.GetFolderPath(Environment.SpecialFolder.Windows);if(Same(target,windows)||Within(target,windows)||Same(target,DataPath)||Within(target,DataPath))throw new Exception("这个位置用于系统或用户数据，不能作为程序安装目录");if(Directory.Exists(target)&&Directory.GetFileSystemEntries(target).Length>0&&!IsInstalled(target))throw new Exception("这个文件夹已有其他文件，请选择空文件夹或现有 TV 助手安装目录");if(!string.IsNullOrWhiteSpace(previous)&&IsInstalled(previous)&&!Same(target,previous)&&(Within(target,previous)||Within(previous,target)))throw new Exception("新旧安装目录不能互相嵌套，请选择旧目录本身或另一独立目录");return target;}
 static void Report(Action<InstallProgress> progress,int percent,string message,bool committing=false){if(progress!=null)progress(new InstallProgress{Percent=percent,Message=message,Committing=committing});}
 public static InstallState Install(InstallOptions options,Action<InstallProgress> progress,CancellationToken token){string target=ValidateTarget(options.Target,options.Previous);string stage=target+".new-"+Guid.NewGuid().ToString("N"),backup=target+".previous-"+DateTime.UtcNow.ToString("yyyyMMddHHmmssfff")+"-"+Guid.NewGuid().ToString("N").Substring(0,6);bool moved=false,committed=false;var files=new HashSet<string>(StringComparer.OrdinalIgnoreCase);try{Report(progress,1,"准备安装目录");token.ThrowIfCancellationRequested();Directory.CreateDirectory(Path.GetDirectoryName(target));Directory.CreateDirectory(stage);using(var resource=Assembly.GetExecutingAssembly().GetManifestResourceStream("payload.zip")){if(resource==null)throw new Exception("没有安装资源，请运行完整 Setup 安装程序");using(var zip=new ZipArchive(resource,ZipArchiveMode.Read)){var entries=zip.Entries.Where(e=>!string.IsNullOrEmpty(e.Name)).ToList();int index=0;foreach(var entry in entries){token.ThrowIfCancellationRequested();string destination=Inside(stage,entry.FullName);Directory.CreateDirectory(Path.GetDirectoryName(destination));entry.ExtractToFile(destination,true);files.Add(entry.FullName.Replace('/',Path.DirectorySeparatorChar));index++;Report(progress,5+(int)(65.0*index/Math.Max(1,entries.Count)),"解压组件 "+index+" / "+entries.Count+" · "+entry.FullName);}}}if(!File.Exists(Path.Combine(stage,"TVStudio.exe"))||!File.Exists(Path.Combine(stage,"adb.exe"))||!File.Exists(Path.Combine(stage,"Uninstall.exe")))throw new Exception("安装资源不完整");Report(progress,72,"关闭旧版程序与专用 ADB");if(!string.IsNullOrWhiteSpace(options.Previous)&&!Same(options.Previous,target)&&IsInstalled(options.Previous)){CloseApp(options.Previous);StopAdb(options.Previous);}CloseApp(target);StopAdb(target);token.ThrowIfCancellationRequested();ValidateTarget(target,options.Previous);Report(progress,80,"写入程序并保留旧版备份",true);if(Directory.Exists(target)){if(!backup.StartsWith(target+".previous-",StringComparison.OrdinalIgnoreCase)||Directory.Exists(backup))throw new Exception("备份目录无效");MoveInstallDirectory(target,backup);moved=true;}MoveInstallDirectory(stage,target);committed=true;var state=new InstallState{Product=ProductId,Version=Version,Target=target,Data=DataPath,Backup=moved?backup:"",Files=files.OrderBy(x=>x).ToList(),Desktop=options.Desktop,StartMenu=options.StartMenu};File.WriteAllText(Path.Combine(target,StateName),new JavaScriptSerializer().Serialize(state));if(options.Register){Report(progress,88,"注册卸载入口",true);Register(state);Report(progress,94,"创建所选快捷方式",true);try{CreateShortcuts(state);}catch(Exception ex){Report(progress,96,"程序已安装；快捷方式创建失败，可从安装目录启动："+ex.Message,true);}}Report(progress,100,"安装完成",true);return state;}catch{if(moved&&!committed&&!Directory.Exists(target)&&Directory.Exists(backup))MoveInstallDirectory(backup,target);throw;}finally{if(Directory.Exists(stage)){string resolved=Path.GetFullPath(stage);if(resolved.StartsWith(Path.GetFullPath(target)+".new-",StringComparison.OrdinalIgnoreCase)&&System.Text.RegularExpressions.Regex.IsMatch(Path.GetFileName(resolved),@"\.new-[a-f0-9]{32}$"))Directory.Delete(resolved,true);}}}
 static void Register(InstallState state){using(var key=Registry.CurrentUser.CreateSubKey(RegistryPath)){key.SetValue("DisplayName","瞎折腾 TV 助手");key.SetValue("DisplayVersion",Version);key.SetValue("Publisher","瞎折腾");key.SetValue("DisplayIcon",Path.Combine(state.Target,"TVStudio.exe"));key.SetValue("InstallLocation",state.Target);key.SetValue("UninstallString",Q(Path.Combine(state.Target,"Uninstall.exe"))+" --uninstall");key.SetValue("NoModify",1);key.SetValue("NoRepair",1);}}
 static string DesktopLink{get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),"瞎折腾 TV Studio.lnk");}}
 static string MenuFolder{get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Programs),"瞎折腾 TV 助手");}}
 static void Link(string path,string exe,string folder){Type type=Type.GetTypeFromProgID("WScript.Shell");dynamic shell=Activator.CreateInstance(type);dynamic link=shell.CreateShortcut(path);try{link.TargetPath=exe;link.WorkingDirectory=folder;link.IconLocation=exe+",0";link.Save();}finally{System.Runtime.InteropServices.Marshal.FinalReleaseComObject(link);System.Runtime.InteropServices.Marshal.FinalReleaseComObject(shell);}}
 static void CreateShortcuts(InstallState state){string exe=Path.Combine(state.Target,"TVStudio.exe");if(state.Desktop)Link(DesktopLink,exe,state.Target);if(state.StartMenu){Directory.CreateDirectory(MenuFolder);Link(Path.Combine(MenuFolder,"瞎折腾 TV 助手.lnk"),exe,state.Target);}}
 public static void Uninstall(string target,bool registration,Action<InstallProgress> progress){target=ValidateTarget(target);string manifest=Path.Combine(target,StateName);if(!File.Exists(manifest))throw new Exception("未找到安装清单，请先用安装程序修复，再卸载");var state=new JavaScriptSerializer().Deserialize<InstallState>(File.ReadAllText(manifest));if(state==null||state.Product!=ProductId||!Same(state.Target,target)||state.Files==null)throw new Exception("安装清单与目录不匹配，已停止卸载");var paths=state.Files.Select(relative=>Inside(target,relative)).ToList();Report(progress,5,"关闭程序和专用 ADB",true);CloseApp(target);StopAdb(target);int count=0;foreach(string file in paths){if(Same(file,Assembly.GetExecutingAssembly().Location))continue;if(File.Exists(file))File.Delete(file);count++;Report(progress,10+(int)(75.0*count/Math.Max(1,paths.Count)),"移除程序文件 · "+Path.GetFileName(file),true);}if(registration&&Same(RegisteredPath(),target)){Report(progress,90,"移除当前安装的快捷方式和卸载入口",true);if(File.Exists(DesktopLink))File.Delete(DesktopLink);string menu=Path.Combine(MenuFolder,"瞎折腾 TV 助手.lnk");if(File.Exists(menu))File.Delete(menu);if(Directory.Exists(MenuFolder)&&Directory.GetFileSystemEntries(MenuFolder).Length==0)Directory.Delete(MenuFolder,false);Registry.CurrentUser.DeleteSubKeyTree(RegistryPath,false);}if(File.Exists(manifest))File.Delete(manifest);var directories=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(string file in paths){string dir=Path.GetDirectoryName(file);while(Within(dir,target)){directories.Add(dir);dir=Path.GetDirectoryName(dir);}}foreach(string dir in directories.OrderByDescending(x=>x.Length))if(Within(dir,target)&&Directory.Exists(dir)&&Directory.GetFileSystemEntries(dir).Length==0)Directory.Delete(dir,false);if(Directory.Exists(target)&&Directory.GetFileSystemEntries(target).Length==0)Directory.Delete(target,false);Report(progress,100,"卸载完成，用户数据和额外文件已保留",true);}
 static void CloseApp(string dir){if(!File.Exists(Path.Combine(dir,"TVStudio.exe")))return;foreach(var p in Process.GetProcessesByName("TVStudio")){try{string executable;try{executable=p.MainModule.FileName;}catch(System.ComponentModel.Win32Exception){continue;}catch(InvalidOperationException){continue;}if(!Same(Path.GetDirectoryName(executable),dir))continue;if(!p.CloseMainWindow()||!p.WaitForExit(10000))throw new Exception("请先退出当前安装目录下的 TV 助手，再继续");}finally{p.Dispose();}}}
 static void StopAdb(string dir){string exe=Path.Combine(dir,"adb.exe");if(!File.Exists(exe))return;var owned=new List<Process>();foreach(var candidate in Process.GetProcessesByName("adb")){try{if(Same(candidate.MainModule.FileName,exe))owned.Add(candidate);else candidate.Dispose();}catch{candidate.Dispose();}}if(owned.Count==0)return;try{using(var p=Process.Start(new ProcessStartInfo(exe,"-P 15037 kill-server"){UseShellExecute=false,CreateNoWindow=true})){if(!p.WaitForExit(10000)||p.ExitCode!=0)throw new Exception("专用 ADB 未正常退出，请先关闭本工具后重试");}foreach(var p in owned)if(!p.WaitForExit(5000))throw new Exception("本工具 ADB 仍被占用，请稍后重试");}finally{foreach(var p in owned)p.Dispose();}}
 [STAThread]public static int Main(string[] args){bool own;using(var mutex=new Mutex(false,"Local\\XiaZheTengTVSetup",out own)){try{own=mutex.WaitOne(args.Contains("--uninstall-target")?10000:0);}catch(AbandonedMutexException){own=true;}if(!own)return 2;try{if(args.Length==2&&(args[0]=="--test-target"||args[0]=="--test-uninstall-target")){File.WriteAllText("setup-test-progress.log","");Action<InstallProgress> report=p=>File.AppendAllText("setup-test-progress.log",p.Percent+"\t"+p.Message+Environment.NewLine);if(args[0]=="--test-target")Install(new InstallOptions{Target=args[1],Register=false,Desktop=false,StartMenu=false},report,CancellationToken.None);else Uninstall(args[1],false,report);return 0;}bool uninstall=args.Contains("--uninstall")||string.Equals(Path.GetFileName(Assembly.GetExecutingAssembly().Location),"Uninstall.exe",StringComparison.OrdinalIgnoreCase)||args.Contains("--uninstall-target");string target="";if(args.Length==2&&args[0]=="--uninstall-target")target=args[1];else if(uninstall){target=Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location);if(File.Exists(Path.Combine(target,StateName))){string temp=Path.Combine(Path.GetTempPath(),"XZT-Uninstall-"+Guid.NewGuid().ToString("N")+".exe");File.Copy(Assembly.GetExecutingAssembly().Location,temp);mutex.ReleaseMutex();own=false;Process.Start(new ProcessStartInfo(temp,"--uninstall-target "+Q(target)){UseShellExecute=false});return 0;}}else{target=RegisteredPath();if(string.IsNullOrWhiteSpace(target))target=DefaultPath;}var app=new Application();var wizard=new SetupWizard(target,uninstall);app.Run(wizard);return wizard.ResultCode;}catch(Exception ex){if(args.Any(a=>a.StartsWith("--test-")))File.WriteAllText("setup-test-error.txt",ex.ToString());else MessageBox.Show("安装操作失败："+ex.Message,"瞎折腾 TV 助手");return 1;}finally{if(own)try{mutex.ReleaseMutex();}catch(ApplicationException){}}}}
